// ui/stories.js - Модуль интерактивных историй

import { $, $$ } from '../src/utils.js';
import { CONTENT_INDEX } from './home.js';
import { loadContentIndex, loadChapterData } from '../src/content-loader.js';
import { storyOccurrenceIndex } from '../src/dictionary/story-occurrence-index.js';
import { formatLessonLabel, sameLessonId } from '../src/courses/course-context.js';

// Локальный контекст зависимостей
let deps = null;

// Глобальные переменные для квиза
let currentQuestionIndex = 0;
let attemptsCount = 0;

// Функция рендеринга списка историй
export function renderStories(state, dependencies) {
  if (dependencies) deps = dependencies;
  const { chState } = deps;
  const $$ = deps?.$$ || window.$$ || ((s) => Array.from(document.querySelectorAll(s)));
  const toast = deps?.toast || window.toast || (() => {});
  const nav = deps?.nav || window.nav || (() => {});
  const markActivity = deps?.markActivity || window.markActivity || ((toastFn) => {});
  const emptyState = (icon, title, desc) =>
    `<div class="empty"><div class="em">${icon}</div><h3>${title}</h3><p>${desc}</p></div>`;

  // Привязка вкладок библиотеки (Грамматика / Заметки / Истории)
  $$('.lib-tab[data-libtab]').forEach((tab) => {
    tab.classList.toggle('active', tab.dataset.libtab === 'stories');
    tab.onclick = () => {
      $$('.lib-tab[data-libtab]').forEach((t) => t.classList.toggle('active', t === tab));
      if (tab.dataset.libtab === 'notes') {
        renderLibraryNotes(state, dependencies);
      } else if (tab.dataset.libtab === 'grammar') {
        renderLibraryGrammar(state, dependencies);
      } else {
        renderStories(state, dependencies);
      }
    };
  });

  const body = $('#library-body');

  // Список историй строится из лёгкого content-index (без полного контента)
  const stories = CONTENT_INDEX.filter((ch) => ch.storyMeta).map((ch) => ({
    id: ch.storyMeta.storyId,
    lesson_id: ch.id,
    title: ch.storyMeta.title,
    cover_url: ch.storyMeta.cover_url,
  }));

  if (stories.length === 0) {
    body.innerHTML = emptyState(
      '📖',
      'Историй пока нет',
      'Скоро здесь появятся интересные истории!'
    );
    return;
  }

  body.innerHTML = stories
    .map((story) => {
      const isUnlocked = chState(story.lesson_id).started;
      const lockedClass = isUnlocked ? '' : 'story-locked';

      return `
      <div class="story-card ${lockedClass}" data-story-id="${story.id}" data-testid="story-${story.id}">
        <div class="story-cover-wrap">
          <img src="${story.cover_url}" alt="${story.title}" class="story-cover" loading="lazy" />
          ${!isUnlocked ? '<div class="story-lock-overlay"><span class="story-lock-icon">🔒</span></div>' : ''}
        </div>
        <div class="story-info">
          <h3 class="story-title">${story.title}</h3>
          <p class="story-lesson">${formatLessonLabel(story.lesson_id)}</p>
        </div>
      </div>
    `;
    })
    .join('');

  $$('.story-card').forEach((card) => {
    card.onclick = async () => {
      const storyId = card.dataset.storyId;
      const storyMeta = stories.find((s) => String(s.id) === storyId);
      if (!storyMeta) return;

      const isUnlocked = chState(storyMeta.lesson_id).started;

      if (!isUnlocked) {
        toast(`🔒 Пройдите «${formatLessonLabel(storyMeta.lesson_id)}», чтобы открыть эту историю`);
        return;
      }

      // Полный контент истории подгружаем только при открытии
      try {
        const { story } = await loadChapterData(storyMeta.lesson_id);
        if (!story) throw new Error('story chunk missing');
        openStory(story, state, dependencies);
      } catch (e) {
        console.error('Не удалось загрузить историю:', e);
        toast('⚠️ Не удалось загрузить историю');
      }
    };
  });
}

// Локальный экранировщик HTML для пользовательского контента
function escapeHtmlLocal(s) {
  return String(s ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

const expandedNoteIds = new Set();

function isLongNote(content) {
  if (!content) return false;
  if (content.length > 500) return true;
  const lines = content.split('\n').length;
  return lines > 8;
}

// Вкладка «Заметки» — сохранённые ответы Сенсея
export function renderLibraryNotes(state, dependencies) {
  const { save } = deps || dependencies;
  const body = $('#library-body');
  if (!body) return;

  const notes = state.savedNotes || [];
  if (notes.length === 0) {
    body.innerHTML = `<div class="empty"><div class="em">📝</div><h3>Заметок пока нет</h3><p>Сохраняйте ответы Сенсея кнопкой «＋ Сохранить в учебник».</p></div>`;
    return;
  }

  body.innerHTML = notes
    .map((n) => {
      const isLong = isLongNote(n.content);
      const isExpanded = expandedNoteIds.has(n.id);
      const contentClass = isLong
        ? isExpanded
          ? 'note-content note-content-expanded'
          : 'note-content note-content-collapsed'
        : 'note-content note-content-expanded';

      const toggleBtn = isLong
        ? `<button type="button" class="btn-ghost note-toggle" aria-expanded="${isExpanded}" aria-controls="note-content-${escapeHtmlLocal(n.id)}">${isExpanded ? 'Свернуть' : 'Развернуть'}</button>`
        : '';

      return `
      <article class="note-card" data-note-id="${escapeHtmlLocal(n.id)}">
        <header class="note-head">
          <h3 class="note-title">${escapeHtmlLocal(n.title)}</h3>
          <span class="note-date">${escapeHtmlLocal(n.date || '')}</span>
        </header>
        <div class="${contentClass}" id="note-content-${escapeHtmlLocal(n.id)}">${escapeHtmlLocal(n.content)}</div>
        <footer class="note-actions">
          ${toggleBtn}
          <button type="button" class="btn-ghost note-delete">Удалить</button>
        </footer>
      </article>`;
    })
    .join('');

  body.querySelectorAll('.note-toggle').forEach((btn) => {
    btn.onclick = (e) => {
      e.stopPropagation();
      const card = btn.closest('.note-card');
      const id = card?.dataset.noteId;
      if (!id) return;
      if (expandedNoteIds.has(id)) {
        expandedNoteIds.delete(id);
      } else {
        expandedNoteIds.add(id);
      }
      renderLibraryNotes(state, dependencies);
    };
  });

  body.querySelectorAll('.note-delete').forEach((btn) => {
    btn.onclick = (e) => {
      e.stopPropagation();
      const card = btn.closest('.note-card');
      const id = card?.dataset.noteId;
      if (!id) return;
      expandedNoteIds.delete(id);
      state.savedNotes = (state.savedNotes || []).filter((n) => n.id !== id);
      storyOccurrenceIndex.invalidate();
      save();
      renderLibraryNotes(state, dependencies);
    };
  });
}

// Вкладка «Грамматика» — горизонтальные кнопки глав + карточки грамматики
async function renderLibraryGrammar(state, dependencies) {
  const { chState } = deps || dependencies;
  const body = $('#library-body');
  if (!body) return;

  if (!CONTENT_INDEX || CONTENT_INDEX.length === 0) {
    body.innerHTML = `<div class="empty"><div class="em">📚</div><h3>Уроки не загружены</h3></div>`;
    return;
  }

  // Определяем активную главу (первая разблокированная или первая)
  let activeChapterId = state.activeGrammarChapter || CONTENT_INDEX[0]?.id || null;
  const activeChapter = CONTENT_INDEX.find((ch) => sameLessonId(ch.id, activeChapterId));
  activeChapterId = activeChapter?.id || CONTENT_INDEX[0]?.id || null;
  const isUnlocked = activeChapter ? chState(activeChapter.id).started : false;

  // Генерируем кнопки глав
  const chaptersButtons = CONTENT_INDEX.map((ch) => {
    const unlocked = chState(ch.id).started;
    const isActive = sameLessonId(ch.id, activeChapterId);
    const lessonNumber = (ch.order ?? CONTENT_INDEX.indexOf(ch)) + 1;
    return `
      <button 
        class="grammar-chapter-btn ${isActive ? 'active' : ''} ${unlocked ? '' : 'locked'}" 
        data-chapter-id="${ch.id}"
        ${unlocked ? '' : 'disabled'}
      >
        ${unlocked ? `Ур.${lessonNumber}` : `Ур.${lessonNumber} 🔒`}
      </button>`;
  }).join('');

  // Генерируем заголовок главы
  const chapterTitle = (activeChapter?.title || formatLessonLabel(activeChapterId)).toUpperCase();

  // Показываем лоадер перед загрузкой
  body.innerHTML = `
    <div class="grammar-chapters-row">
      ${chaptersButtons}
    </div>
    <h2 class="grammar-chapter-title">${chapterTitle}</h2>
    <div class="loader-container">
      <div class="loader"></div>
    </div>
  `;

  // Генерируем карточки грамматики
  let grammarCards = '';
  if (!isUnlocked) {
    grammarCards = `
      <div class="grammar-empty">
        <div class="grammar-empty-icon">🔒</div>
        <p class="grammar-empty-text">Завершите «${formatLessonLabel(activeChapterId)}», чтобы открыть грамматику</p>
      </div>`;
  } else {
    try {
      // Загружаем полные данные урока
      const { lesson } = await loadChapterData(activeChapterId);
      const notes = lesson?.notes || [];

      if (notes.length > 0) {
        grammarCards = notes
          .map(
            (note) => `
          <div class="grammar-card">
            <h3 class="grammar-card-title">${escapeHtmlLocal(note.title)}</h3>
            <p class="grammar-card-content">${escapeHtmlLocal(note.content)}</p>
          </div>`
          )
          .join('');
      } else {
        grammarCards = `
          <div class="grammar-empty">
            <div class="grammar-empty-icon">📝</div>
            <p class="grammar-empty-text">В этой главе пока нет грамматических правил</p>
          </div>`;
      }
    } catch (error) {
      grammarCards = `
        <div class="grammar-empty">
          <div class="grammar-empty-icon">⚠️</div>
          <p class="grammar-empty-text">Ошибка загрузки грамматики</p>
        </div>`;
    }
  }

  // Обновляем контент с загруженной грамматикой
  body.innerHTML = `
    <div class="grammar-chapters-row">
      ${chaptersButtons}
    </div>
    <h2 class="grammar-chapter-title">${chapterTitle}</h2>
    ${grammarCards}
  `;

  // Навешиваем обработчики на кнопки глав
  body.querySelectorAll('.grammar-chapter-btn:not(.locked)').forEach((btn) => {
    btn.onclick = () => {
      state.activeGrammarChapter = btn.dataset.chapterId;
      renderLibraryGrammar(state, dependencies);
    };
  });
}

import { normalizeLegacyStoryToken } from '../src/dictionary/token-occurrence.js';
import { dictionaryStore } from '../src/dictionary/dictionary-store.js';
import { resolveStoryTokens } from '../src/ai/story-token-resolver.js';

// Функция рендеринга интерактивной истории с токенами
function renderInteractiveStory(content, storyId = 'story') {
  if (!Array.isArray(content)) return '';

  return content
    .map((sentence, sIdx) => {
      const sentenceId = sentence.sentence_id ?? sentence.sentenceId ?? sIdx + 1;
      const tokensHtml = (sentence.tokens || [])
        .map((tok, tokenIndex) => {
          const rawToken = tok || {};
          const occ = normalizeLegacyStoryToken(
            {
              ...rawToken,
              dictionaryId: rawToken.dictionaryId || rawToken.lexemeId || rawToken.knowledgeItemId,
            },
            { storyId, sentenceId, tokenIndex }
          );

          if (occ.resolution?.status === 'non-lexical') {
            return escapeHtmlLocal(occ.surface);
          }

          const surface = escapeHtmlLocal(occ.surface);
          const reading = escapeHtmlLocal(occ.reading);
          const dictionaryId = escapeHtmlLocal(occ.dictionaryId || '');
          const contextMeaning = escapeHtmlLocal(occ.contextMeaning || '');
          const status = escapeHtmlLocal(occ.resolution.status);
          const tokenId = escapeHtmlLocal(occ.id);
          const posType = escapeHtmlLocal(rawToken.type || 'Word');
          const tense = escapeHtmlLocal(occ.form?.tense || '');
          const politeness = escapeHtmlLocal(occ.form?.politeness || '');
          const polarity = escapeHtmlLocal(occ.form?.polarity || '');
          const conjugation = escapeHtmlLocal(occ.form?.conjugation || '');

          if (reading && reading !== surface) {
            return `<ruby><span class="word-token" 
                  data-token-id="${tokenId}"
                  data-story-id="${escapeHtmlLocal(storyId || '')}"
                  data-sentence-id="${escapeHtmlLocal(String(sentenceId))}"
                  data-dictionary-id="${dictionaryId}"
                  data-surface="${surface}"
                  data-reading="${reading}"
                  data-context-meaning="${contextMeaning}"
                  data-resolution-status="${status}"
                  data-form-tense="${tense}"
                  data-form-politeness="${politeness}"
                  data-form-polarity="${polarity}"
                  data-form-conjugation="${conjugation}"
                  data-kanji="${surface}"
                  data-writing="${reading}"
                  data-translation="${contextMeaning}"
                  data-type="${posType}">${surface}</span><rt>${reading}</rt></ruby>`;
          }

          return `<span class="word-token" 
                data-token-id="${tokenId}"
                data-story-id="${escapeHtmlLocal(storyId || '')}"
                data-sentence-id="${escapeHtmlLocal(String(sentenceId))}"
                data-dictionary-id="${dictionaryId}"
                data-surface="${surface}"
                data-reading="${reading}"
                data-context-meaning="${contextMeaning}"
                data-resolution-status="${status}"
                data-form-tense="${tense}"
                data-form-politeness="${politeness}"
                data-form-polarity="${polarity}"
                data-form-conjugation="${conjugation}"
                data-kanji="${surface}"
                data-translation="${contextMeaning}"
                data-type="${posType}">${surface}</span>`;
        })
        .join('');

      return `
      <div class="story-sentence" data-story-id="${escapeHtmlLocal(storyId || '')}" data-sentence-id="${escapeHtmlLocal(String(sentenceId))}">
        ${sentence.speaker ? `<strong class="speaker">${escapeHtmlLocal(sentence.speaker)}:</strong>` : ''}
        <p class="sentence-jp">${tokensHtml}</p>
        <button class="toggle-translation-btn">Показать перевод</button>
        <p class="sentence-translation hidden">${escapeHtmlLocal(sentence.translation)}</p>
      </div>
    `;
    })
    .join('');
}

let bottomSheetReturnFocus = null;

// Функция открытия Bottom Sheet для перевода слова
export function openWordBottomSheet(tokenElement, customStore = null) {
  const sheet = $('#word-bottom-sheet');
  if (!sheet) return;

  bottomSheetReturnFocus = tokenElement || document.activeElement;

  const dataset = tokenElement.dataset || {};
  const surface = dataset.surface || dataset.kanji || '';
  const reading = dataset.reading || dataset.writing || surface;
  const contextMeaning = dataset.contextMeaning || dataset.translation || '';
  const dictionaryId = dataset.dictionaryId || null;
  const resolutionStatus = dataset.resolutionStatus || 'resolved';

  const modalTokenSurface = $('#modal-token-surface');
  const modalTokenReading = $('#modal-token-reading');
  const modalContextMeaning = $('#modal-context-meaning');
  const modalDictForm = $('#modal-dictionary-form');
  const modalDictReading = $('#modal-dictionary-reading');
  const modalDictMeanings = $('#modal-dictionary-meanings');

  const modalKanji = $('#modal-kanji');
  const modalReading = $('#modal-reading');
  const modalTranslation = $('#modal-translation');
  const modalType = $('#modal-type');
  const modalSource = $('#modal-source');
  const openPageBtn = $('#btn-open-word-page');

  let entry = null;
  const activeStore = customStore || dictionaryStore || window.dictionaryStore || null;
  if (dictionaryId && activeStore && typeof activeStore.getDictionaryEntry === 'function') {
    entry = activeStore.getDictionaryEntry(dictionaryId);
  }

  // Token occurrence details
  if (modalTokenSurface) modalTokenSurface.textContent = surface;
  if (modalTokenReading) modalTokenReading.textContent = reading !== surface ? reading : '';
  if (modalContextMeaning) modalContextMeaning.textContent = contextMeaning;

  // Dictionary entry details
  if (modalDictForm) {
    if (entry) {
      modalDictForm.textContent = entry.dictionaryForm;
    } else if (resolutionStatus === 'missing' || resolutionStatus === 'dangling') {
      modalDictForm.textContent = 'Словарная запись не найдена';
    } else if (resolutionStatus === 'ambiguous') {
      modalDictForm.textContent = 'Не удалось однозначно определить словарную запись';
    } else {
      modalDictForm.textContent = '';
    }
  }

  if (modalDictReading)
    modalDictReading.textContent =
      entry?.reading && entry.reading !== entry.dictionaryForm ? entry.reading : '';
  if (modalDictMeanings)
    modalDictMeanings.textContent = entry?.meanings ? entry.meanings.join(', ') : '';

  // Legacy elements support
  if (modalKanji) modalKanji.textContent = entry?.dictionaryForm || surface;
  if (modalReading) {
    const displayReading =
      reading !== surface ? reading : entry?.reading !== surface ? entry?.reading : '';
    modalReading.textContent = displayReading || '';
  }

  if (modalTranslation) {
    const globalMeanings = entry?.meanings ? entry.meanings.join(', ') : '';
    if (resolutionStatus === 'non-lexical') {
      modalTranslation.textContent = 'Служебный элемент';
    } else if (resolutionStatus === 'missing') {
      modalTranslation.textContent = 'Слово не найдено в словаре';
    } else if (resolutionStatus === 'ambiguous') {
      modalTranslation.textContent = contextMeaning || globalMeanings || 'Неоднозначное слово';
    } else if (contextMeaning && globalMeanings && contextMeaning !== globalMeanings) {
      modalTranslation.textContent = `${contextMeaning} (Значения: ${globalMeanings})`;
    } else {
      modalTranslation.textContent =
        contextMeaning || globalMeanings || 'Слово не найдено в словаре';
    }
  }

  if (modalType) {
    const srcTag =
      entry?.source === 'ai' ? ' [AI]' : entry?.source === 'curated' ? ' [Словарь]' : '';
    modalType.textContent =
      (entry?.partOfSpeech ? _posLabel(entry.partOfSpeech) : dataset.type || 'Слово') + srcTag;
  }

  if (modalSource) {
    if (entry?.source === 'curated') {
      modalSource.textContent = '✓ Проверенная запись KotoKitsu';
      modalSource.className = 'word-source-badge word-source-badge--curated';
    } else if (entry?.source === 'ai') {
      const confStr =
        typeof entry.confidence === 'number' ? ` (${Math.round(entry.confidence * 100)}%)` : '';
      modalSource.textContent = `🤖 Создано AI${confStr}${entry.verified ? ' · Проверено' : ''}`;
      modalSource.className = 'word-source-badge word-source-badge--ai';
    } else {
      modalSource.textContent = '';
      modalSource.className = 'word-source-badge';
    }
  }

  // Show "open word page" button only when dictionaryId and entry exist and status is resolved
  if (openPageBtn) {
    const canOpen = dictionaryId && entry && resolutionStatus === 'resolved';
    openPageBtn.hidden = !canOpen;
    if (canOpen) {
      openPageBtn.onclick = () => {
        closeWordBottomSheet();
        const navFn = window.nav || (() => {});
        navFn('word-details', {
          dictionaryId,
          surface,
          reading: reading !== surface ? reading : null,
          contextMeaning,
          tokenId: dataset.tokenId || null,
          storyId: dataset.storyId || null,
          sentenceId: dataset.sentenceId || null,
          form: {
            tense: dataset.formTense || null,
            politeness: dataset.formPoliteness || null,
            polarity: dataset.formPolarity || null,
            conjugation: dataset.formConjugation || null,
          },
        });
      };
    }
  }

  sheet.classList.add('active');

  const backdrop = sheet.querySelector('.bottom-sheet-backdrop');
  if (backdrop) {
    backdrop.onclick = () => closeWordBottomSheet();
  }

  // Focus management: move focus inside sheet for accessibility
  const firstFocusable = sheet.querySelector('button:not([hidden]), [tabindex="0"]');
  if (firstFocusable) {
    requestAnimationFrame(() => firstFocusable.focus());
  }
}

// Локализация части речи
function _posLabel(pos) {
  const labels = {
    noun: 'Существительное',
    verb: 'Глагол',
    adjective: 'Прилагательное',
    adverb: 'Наречие',
    particle: 'Частица',
    expression: 'Выражение',
  };
  return labels[pos] || pos || 'Слово';
}

// Функция закрытия Bottom Sheet
export function closeWordBottomSheet() {
  const sheet = $('#word-bottom-sheet');
  if (sheet) sheet.classList.remove('active');

  if (bottomSheetReturnFocus && typeof bottomSheetReturnFocus.focus === 'function') {
    try {
      bottomSheetReturnFocus.focus();
    } catch {
      // ignore focus errors
    }
    bottomSheetReturnFocus = null;
  }
}

/**
 * Route handler to navigate to and render a story with optional sentence & token highlight.
 *
 * @param {object} state
 * @param {object} dependencies
 * @param {object} options — { storyId, sentenceId, tokenId, highlight }
 * @param {object} [context] — { signal }
 */
export async function renderStoryRoute(state, dependencies, options = {}, context = {}) {
  const signal = context?.signal;
  const storyId = String(options?.storyId ?? '');
  const navFn = dependencies?.nav || window.nav || (() => {});

  if (!storyId) {
    if (typeof navFn === 'function') {
      navFn('library', {}, true);
    } else {
      renderStories(state, dependencies);
    }
    return;
  }

  // 1. Check if storyId matches a saved note (AI story)
  const savedNotes = state?.savedNotes || [];
  const savedNote = savedNotes.find(
    (n) =>
      n && (n.id === storyId || n.sourceStoryId === storyId || String(n.id) === String(storyId))
  );

  let storyToOpen = null;
  if (savedNote && Array.isArray(savedNote.story)) {
    storyToOpen = {
      id: savedNote.id,
      storyId: savedNote.id,
      title: savedNote.title || 'История AI',
      content: savedNote.story,
      source: 'ai',
      courseId: savedNote.courseId || options.courseId || null,
    };
  } else {
    // 2. Builtin course story: extract lessonId from storyId or options or contentIndex
    const rawStoryId = storyId.includes(':story:')
      ? storyId.split(':story:')[1]
      : storyId.includes(':')
        ? storyId.split(':').pop()
        : storyId;
    const targetCourseId =
      options.courseId ||
      (storyId.includes(':') ? storyId.split(':')[0] : state?.activeCourseId || 'genki-1');
    let lessonId = options.lessonId;

    if (!lessonId) {
      try {
        const contentIndex = await loadContentIndex(targetCourseId);
        const chapters = contentIndex?.chapters || [];
        const chapter = chapters.find((c) => {
          if (!c) return false;
          const sMetaId = c.storyMeta?.storyId != null ? String(c.storyMeta.storyId) : null;
          const cId = c.id != null ? String(c.id) : null;
          const cleanRaw = String(rawStoryId).replace(/^lesson-/, '');
          return (
            sMetaId === String(rawStoryId) ||
            cId === String(rawStoryId) ||
            cId === cleanRaw ||
            (sMetaId && storyId === `${targetCourseId}:story:${sMetaId}`) ||
            (cId && storyId === `${targetCourseId}:story:${cId}`) ||
            (cId && storyId === `${targetCourseId}:story:lesson-${cId}`)
          );
        });
        if (chapter) {
          lessonId = chapter.id;
        }
      } catch (err) {
        // ignore index load fallback
      }
    }

    if (!lessonId) {
      if (storyId.includes(':story:')) {
        lessonId = storyId.split(':story:')[1];
      } else if (storyId.includes(':')) {
        lessonId = storyId.split(':')[1];
      } else {
        lessonId = storyId;
      }
    }

    try {
      let loaded = await loadChapterData(lessonId, targetCourseId).catch(() => null);
      if (!loaded?.story && String(lessonId).startsWith('lesson-')) {
        const canonicalKey = `${targetCourseId}:${lessonId}`;
        loaded = await loadChapterData(canonicalKey, targetCourseId).catch(() => null);
      }
      if (signal?.aborted) return;
      if (loaded?.story) {
        storyToOpen = loaded.story;
      }
    } catch (err) {
      console.warn('[Stories] Could not load story chunk for route:', err);
    }
  }

  if (signal?.aborted) return;

  if (!storyToOpen) {
    const storyBody = $('#story-body');
    if (storyBody) {
      storyBody.innerHTML = `
        <div class="story-content">
          <div class="story-meta">
            <span class="badge badge-warning">История не найдена</span>
          </div>
          <div class="story-text">
            <p>Запрошенная история не найдена.</p>
          </div>
          <div class="story-actions" style="margin-top: 16px;">
            <button class="btn-primary" onclick="window.nav && window.nav('library')">
              📚 Вернуться в библиотеку
            </button>
          </div>
        </div>`;
    } else if (typeof navFn === 'function') {
      navFn('library', {}, true);
    }
    return;
  }

  // 3. Render story content directly (route handler is already on story route)
  await renderStoryContent(storyToOpen, state, dependencies, {
    courseId: options.courseId,
    signal,
  });
  if (signal?.aborted) return;

  // 4. Handle sentence scrolling & token highlight
  const safeCss = (str) =>
    typeof window !== 'undefined' && window.CSS && typeof window.CSS.escape === 'function'
      ? window.CSS.escape(String(str))
      : String(str).replace(/"/g, '\\"');
  const { sentenceId, tokenId, highlight } = options;
  if (sentenceId != null) {
    const sentenceEl = document.querySelector(
      `.story-sentence[data-sentence-id="${safeCss(sentenceId)}"]`
    );
    if (sentenceEl) {
      if (typeof sentenceEl.scrollIntoView === 'function') {
        sentenceEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
      }
    }
  }

  if (tokenId && highlight !== false) {
    const tokenEl = document.querySelector(`.word-token[data-token-id="${safeCss(tokenId)}"]`);
    if (tokenEl) {
      tokenEl.classList.add('word-token-highlighted');
      setTimeout(() => {
        tokenEl.classList.remove('word-token-highlighted');
      }, 3500);
    }
  }
}

// Закрытие по нажатию Escape
if (typeof document !== 'undefined') {
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      const sheet = document.getElementById('word-bottom-sheet');
      if (sheet && sheet.classList.contains('active')) {
        closeWordBottomSheet();
      }
    }
  });
}

// Функция установки обработчиков клика по токенам и переключения переводов
function setupStoryInteractions() {
  const buttons = $$('.toggle-translation-btn');
  buttons.forEach((btn) => {
    btn.onclick = (e) => {
      e.stopPropagation();
      const translation = btn.nextElementSibling;
      if (translation && translation.classList.contains('sentence-translation')) {
        const isHidden = translation.classList.toggle('hidden');
        btn.textContent = isHidden ? 'Показать перевод' : 'Скрыть перевод';
      }
    };
  });

  const tokens = $$('.word-token');
  tokens.forEach((tok) => {
    tok.onclick = (e) => {
      e.stopPropagation();
      openWordBottomSheet(tok);
    };
  });
}

// Функция рендеринга содержимого истории
export async function renderStoryContent(story, state, dependencies, options = {}) {
  const signal = options?.signal;
  if (signal?.aborted) return;

  const storyTitle = $('#story-title');
  const storyTitleJp = $('#story-title-jp');

  if (storyTitle) storyTitle.textContent = story.title;
  if (storyTitleJp) storyTitleJp.textContent = story.titleJP || '';

  const sourceCourseId = options?.courseId || story.courseId || state?.activeCourseId || 'genki-1';
  const rawId = story.id || story.storyId || 'story';
  const isAi = story.source === 'ai' || String(rawId).startsWith('ai-story');
  const storyId =
    isAi || String(rawId).includes(':') ? String(rawId) : `${sourceCourseId}:story:${rawId}`;
  let contentToRender = story.content || [];

  try {
    const resolved = await resolveStoryTokens({
      story: contentToRender,
      dictionaryStore,
      activeCourseId: sourceCourseId,
      storyId,
    });
    if (signal?.aborted) return;
    contentToRender = resolved.story || contentToRender;
  } catch (err) {
    console.warn('[Stories] Could not resolve built-in story tokens:', err);
  }

  if (signal?.aborted) return;

  const storyBody = $('#story-body');
  if (storyBody) {
    if (signal?.aborted) return;
    storyBody.innerHTML = `
  <div class="story-content">
    <div class="story-meta">
      <span class="story-lesson-badge">${formatLessonLabel(story.lessonId || story.lesson_id)}</span>
    </div>
    <div class="story-text">${renderInteractiveStory(contentToRender, storyId)}</div>
    ${
      story.questions && story.questions.length > 0
        ? `
      <div class="story-actions">
        <button id="btn-finish-story" class="btn-primary-large">
          📖 Завершить историю
        </button>
      </div>
    `
        : ''
    }
  </div>
  `;
  }

  if (signal?.aborted) return;
  setupStoryInteractions();

  const finishBtn = document.getElementById('btn-finish-story');
  if (finishBtn) {
    finishBtn.onclick = () => {
      startStoryQuiz(story, state, dependencies);
    };
  }
}

// Переход к истории с триггеров вне роутера
export async function navigateToStory(story, state, dependencies) {
  const navFn = dependencies?.nav || window.nav || (() => {});
  navFn('story', {
    storyId: story.id || story.storyId,
    lessonId: story.lessonId || story.lesson_id,
    courseId: story.courseId,
  });
}

export async function openStory(story, state, dependencies) {
  return navigateToStory(story, state, dependencies);
}

// Функция запуска квиза по истории
function startStoryQuiz(story, state, dependencies) {
  if (!story.questions || story.questions.length === 0) {
    story.questions = [
      {
        question: 'Вы внимательно прочитали историю?',
        options: ['Да, всё понятно!', 'Нет, хочу перечитать'],
        correctAnswer: 0,
      },
    ];
  }

  currentQuestionIndex = 0;
  attemptsCount = 0;

  function renderQuestion(index) {
    const q = story.questions[index];
    const storyBody = $('#story-body');

    storyBody.innerHTML = `
      <div class="quiz-container">
        <div class="quiz-header">
          <button class="btn-ghost" id="quiz-back-btn">← Назад к истории</button>
          <div class="quiz-progress">Вопрос ${index + 1} из ${story.questions.length}</div>
        </div>
        <h2 class="quiz-question">${q.question}</h2>
        <div class="quiz-options" id="quiz-options">
          ${q.options
            .map((opt, i) => `<button class="quiz-option-btn" data-index="${i}">${opt}</button>`)
            .join('')}
        </div>
      </div>
    `;

    const backBtn = $('#quiz-back-btn');
    if (backBtn) {
      backBtn.onclick = () => {
        openStory(story, state, dependencies);
      };
    }

    document.querySelectorAll('.quiz-option-btn').forEach((btn) => {
      btn.onclick = () => {
        const selectedIndex = parseInt(btn.dataset.index, 10);
        checkAnswer(selectedIndex, q.correctAnswer, btn);
      };
    });
  }

  function checkAnswer(selectedIndex, correctIndex, buttonElement) {
    const allButtons = document.querySelectorAll('.quiz-option-btn');

    allButtons.forEach((b) => (b.disabled = true));

    if (selectedIndex === correctIndex) {
      buttonElement.classList.add('correct');

      setTimeout(() => {
        currentQuestionIndex++;
        attemptsCount = 0;

        if (currentQuestionIndex < story.questions.length) {
          renderQuestion(currentQuestionIndex);
        } else {
          completeStory(story, state, dependencies);
        }
      }, 1000);
    } else {
      buttonElement.classList.add('incorrect');
      attemptsCount++;

      setTimeout(() => {
        currentQuestionIndex = 0;
        if (dependencies.toast) dependencies.toast('❌ Попробуйте снова с начала');
        renderQuestion(0);
      }, 1500);
    }
  }

  renderQuestion(0);
}

// Функция завершения истории
function completeStory(story, state, dependencies) {
  const {
    save,
    showCompletionScreen,
    XP_PER_LEVEL,
    COINS_PER_LEVEL,
    refreshStreakDisplay,
    toast,
    markActivity,
    nav,
  } = dependencies;

  if (!state.completedStories) state.completedStories = [];

  const isFirstCompletion = !state.completedStories.includes(story.id);

  let xpReward, coinsReward, rewardLabel;

  if (isFirstCompletion) {
    xpReward = story.rewards?.xp || 20;
    coinsReward = story.rewards?.coins || 15;
    rewardLabel = 'Первое прохождение!';

    state.completedStories.push(story.id);
  } else {
    xpReward = 1;
    coinsReward = 0;
    rewardLabel = 'Повторное прохождение';
  }

  state.xp += xpReward;
  state.coins += coinsReward;

  while (state.xp >= XP_PER_LEVEL) {
    state.xp -= XP_PER_LEVEL;
    state.level += 1;
    state.coins += COINS_PER_LEVEL;
    if (typeof toast === 'function') toast(`🎉 Уровень ${state.level}! +${COINS_PER_LEVEL} 🪙`);
  }

  save();
  refreshStreakDisplay();
  if (typeof markActivity === 'function') markActivity(toast);

  const rewards = isFirstCompletion
    ? [
        { icon: '📖', label: rewardLabel },
        { icon: '🪙', label: `+${coinsReward} монет` },
        { icon: '⭐', label: `+${xpReward} XP` },
      ]
    : [
        { icon: '🔄', label: rewardLabel },
        { icon: '⭐', label: `+${xpReward} XP` },
      ];

  showCompletionScreen({
    title: isFirstCompletion ? 'おめでとう!' : 'よくできました!',
    subtitle: story.title,
    desc: isFirstCompletion ? 'История успешно пройдена!' : 'История перечитана!',
    theme: 'success',
    rewards: rewards,
    onContinue: () => {
      if (typeof nav === 'function') nav('library');
    },
  });
}
